<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Models\Booking; use App\Models\SadyaPackage; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class BookingController extends Controller {
 public function index(Request $r){Booking::where('function_date','<',now()->toDateString())->whereIn('status',['Confirmed','Preparation'])->update(['status'=>'Completed']);$q=Booking::with(['customer','package','payments','expenses']);if($r->search)$q->where(fn($x)=>$x->where('booking_number','like','%'.$r->search.'%')->orWhere('venue','like','%'.$r->search.'%')->orWhere('function_type','like','%'.$r->search.'%')->orWhereHas('customer',fn($c)=>$c->where('name','like','%'.$r->search.'%')->orWhere('mobile','like','%'.$r->search.'%')));if($r->status)$q->where('status',$r->status);if($r->from)$q->whereDate('function_date','>=',$r->from);if($r->to)$q->whereDate('function_date','<=',$r->to);$result=$q->orderByDesc('function_date')->paginate($r->integer('per_page',25));$result->getCollection()->each->append(['paid_amount','balance_amount']);return $result;}
 public function store(Request $r){$data=$r->validate(['customer_id'=>'required|exists:customers,id','sadya_package_id'=>'nullable|exists:sadya_packages,id','function_type'=>'required','function_date'=>'required|date','venue'=>'required','notes'=>'nullable|string','guest_count'=>'required|integer|min:1','price_per_leaf'=>'required|numeric|min:0','additional_charges'=>'nullable|numeric|min:0','discount'=>'nullable|numeric|min:0','status'=>'required|in:Enquiry,Confirmed,Preparation,Completed,Cancelled','menu_items'=>'nullable|array','advance_amount'=>'nullable|numeric|min:0']);return DB::transaction(function()use($data){$data['base_amount']=$data['guest_count']*$data['price_per_leaf'];$data['final_amount']=$data['base_amount']+($data['additional_charges']??0)-($data['discount']??0);$data['booking_number']='SC-'.now()->format('ym').'-'.str_pad((string)(Booking::max('id')+1),4,'0',STR_PAD_LEFT);$menu=$data['menu_items']??[];$advance=$data['advance_amount']??0;unset($data['menu_items'],$data['advance_amount']);$b=Booking::create($data);if(!$menu&&$b->sadya_package_id)$menu=SadyaPackage::with('items')->find($b->sadya_package_id)->items->map(fn($i)=>['menu_item_id'=>$i->id,'dish_name'=>$i->name,'included'=>true])->all();$b->menuItems()->createMany($menu);if($advance>0)$b->payments()->create(['payment_date'=>now(),'amount'=>$advance,'payment_mode'=>'Cash','payment_type'=>'Advance']);return response()->json($this->load($b),201);});}
 public function show(Booking $booking){if($booking->function_date<now()->toDateString()&&in_array($booking->status,['Confirmed','Preparation']))$booking->update(['status'=>'Completed']);return $this->load($booking);}
 public function update(Request $r,Booking $booking){if($booking->function_date<=now()->toDateString())return response()->json(['message'=>'Bookings cannot be edited on or after the function date.'],422);return DB::transaction(function()use($r,$booking){$d=$r->all();if(isset($d['guest_count'])||isset($d['price_per_leaf'])||isset($d['additional_charges'])||isset($d['discount'])){$d['base_amount']=($d['guest_count']??$booking->guest_count)*($d['price_per_leaf']??$booking->price_per_leaf);$d['final_amount']=$d['base_amount']+($d['additional_charges']??$booking->additional_charges)-($d['discount']??$booking->discount);}if(isset($d['menu_items'])){$booking->menuItems()->delete();$booking->menuItems()->createMany($d['menu_items']);unset($d['menu_items']);}$booking->update($d);return $this->load($booking);});}
 public function destroy(Booking $booking){if($booking->function_date<=now()->toDateString())return response()->json(['message'=>'Bookings cannot be deleted on or after the function date.'],422);if($booking->payments()->where('direction','in')->exists())return response()->json(['message'=>'Bookings with payments cannot be deleted.'],422);$booking->delete();return response()->noContent();}
 public function cancel(Request $r,Booking $booking){return DB::transaction(function()use($r,$booking){if($booking->status==='Cancelled')return response()->json(['message'=>'Booking is already cancelled.'],422);if($r->boolean('refund')){$paidAmount=$booking->payments()->where('direction','in')->sum('amount');if($paidAmount>0)$booking->payments()->create(['payment_date'=>now(),'amount'=>$paidAmount,'payment_mode'=>'Cash','payment_type'=>'Refund','direction'=>'out']);}$booking->update(['status'=>'Cancelled']);return $this->load($booking);});}
 private function load(Booking $b){$b->load(['customer','package','menuItems','payments','expenses.category']);$b->append(['paid_amount','balance_amount','estimated_profit']);return $b;}
}
